const b=$json.body||$json;
const e=b.event;
const d=b.data||{};
const name=d.customer_name||d.customer||'Pelanggan';
let msg='';
if(e==='booking.created'){msg=`Halo ${name}, booking ${d.booking_number||''} Anda sudah DIKONFIRMASI. Terima kasih telah memesan bersama kami! 🕋`;}
else if(e==='invoice.created'){msg=`Halo ${name}, invoice ${d.invoice_number||''} sebesar ${d.total||d.amount||''} telah terbit. Mohon lakukan pembayaran sebelum ${d.due_date||'jatuh tempo'}.`;}
else if(e==='payment.recorded'||e==='payment.created'){msg=`Halo ${name}, pembayaran sebesar ${d.amount||''} telah kami TERIMA. Terima kasih ✅`;}
else if(e==='payment.reminder'){msg=d.message||`Halo ${name}, pengingat pembayaran invoice ${d.invoice_number||''} (sisa ${d.outstanding||''}), jatuh tempo ${d.due_date||''}.`;}
else if(e==='order.confirmation'){msg=`Halo ${name}, pesanan ${d.booking_number||''} untuk paket ${d.package||''} telah dibuat. Total ${d.total||''}. Tim kami akan segera menghubungi Anda 🙏`;}
else if(e==='conversation.reply'){msg=d.message||'';}
else{msg=`Notifikasi: ${e}`;}
const phone=d.customer_phone||d.whatsapp||d.phone||'';
return [{json:{phone,message:msg,event:e}}];
